   const beast=['bear','cougar','wolf'].includes(e.type);if(beast&&d>90&&d<340&&e.chargeCd<=0){e.charge=.62;e.chargeCd=2.7;state.effects.push({type:'charge',x:e.x,y:e.y,t:.35})}
