function drawSarii(x,y){ctx.save();ctx.translate(x,y);ctx.fillStyle='#b89a74';ctx.beginPath();ctx.ellipse(0,-15,24,13,0,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.arc(22,-25,10,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#6d563e';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(-14,-6);ctx.lineTo(-18,14);ctx.moveTo(8,-7);ctx.lineTo(13,14);ctx.moveTo(-22,-17);ctx.quadraticCurveTo(-37,-34,-33,-43);ctx.stroke();ctx.restore()}
