function drawEntity(e){const x=e.x-state.camera,y=e.y,flash=e.hit>0?.5:1;if(e.type==='feral')drawFeral(x,y,flash);else if(['naru','taabe','trappers','big-beard','raphael','comanche-scouts'].includes(e.type)){if(e.type==='taabe'&&chapter.id==='F11')drawHorse(x,y+28,flash);drawHuman(x,y,e.type,flash);}else{ctx.save();ctx.globalAlpha=flash;ctx.fillStyle=e.type==='bear'?'#3b2e26':e.type==='wolf'?'#65675e':e.type==='cougar'?'#8a6a45':e.type==='snake'?'#53623c':'#80694c';ctx.beginPath();ctx.ellipse(x,y-22,e.type==='bear'?52:32,e.type==='bear'?38:23,0,0,Math.PI*2);ctx.fill();ctx.fillRect(x-22,y-5,8,36);ctx.fillRect(x+14,y-5,8,36);ctx.restore()}if(state.vision){let thermal=e.thermal!==false;ctx.strokeStyle=thermal?'#ff674d':'#6ca6b4';ctx.lineWidth=2;ctx.strokeRect(x-45,y-108,90,154)}if(e.hp<e.maxHp&&e.maxHp<9000){ctx.fillStyle='#241f19';ctx.fillRect(x-35,y-116,70,5);ctx.fillStyle='#a54e40';ctx.fillRect(x-35,y-116,70*Math.max(0,e.hp/e.maxHp),5)}}
function drawPlayer(){const x=state.x-state.camera,y=state.y+(state.crouched?22:0),alpha=state.cloak?.22:1;if(campaign==='feral')drawFeral(x,y,alpha);else{if(chapter.playable==='Taabe'&&chapter.id==='H17')drawHorse(x,y+30,alpha);drawHuman(x,y,chapter.playable,alpha);if(chapter.playable==='Naru')drawSarii(x-52,y+6)}if(state.shield){ctx.strokeStyle='#d8d2b5';ctx.lineWidth=5;ctx.beginPath();ctx.arc(x-28,y-18,38,-1.3,1.3);ctx.stroke()}if(state.damageCd>0&&!settings.reducedFlash){ctx.strokeStyle='#ff675c';ctx.lineWidth=4;ctx.strokeRect(x-36,y-105,72,155)}if(state.heatHidden){ctx.strokeStyle='#84c8d7';ctx.lineWidth=2;ctx.setLineDash([5,4]);ctx.strokeRect(x-38,y-108,76,158);ctx.setLineDash([])}}
function drawTomahawk(){const t=state.tomahawk;if(!t.thrown)return;ctx.strokeStyle='#8c7554';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(state.x-state.camera,state.y-20);ctx.lineTo(t.x-state.camera,t.y);ctx.stroke();ctx.strokeStyle='#d6c29b';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(t.x-state.camera-8,t.y-5);ctx.lineTo(t.x-state.camera+8,t.y+5);ctx.stroke()}
