function loop(now){const dt=Math.min(.033,(now-last)/1000);last=now;update(dt);draw();requestAnimationFrame(loop)}
function buildTimeline(){
 if(ui.syncStrip){const unlocked=new Set(save.mirrors||[]);ui.syncStrip.innerHTML=(CONTENT.parallelSyncPoints||[]).map(s=>`<div class="syncNode ${unlocked.has(s.id)?'unlocked':'locked'}"><b>${s.label}</b><span>${s.human} ↔ ${s.feral}</span><em>${unlocked.has(s.id)?s.note:'Terminez les deux chapitres liés pour ouvrir ce dossier miroir.'}</em>${unlocked.has(s.id)?`<div class="mirrorActions"><button data-mirror-camp="human" data-mirror-chapter="${s.human}">Rejouer ${s.human}</button><button data-mirror-camp="feral" data-mirror-chapter="${s.feral}">Rejouer ${s.feral}</button></div>`:''}</div>`).join('');ui.syncStrip.querySelectorAll('[data-mirror-chapter]').forEach(b=>b.onclick=()=>{const camp=b.dataset.mirrorCamp,id=b.dataset.mirrorChapter,arr=CONTENT[camp]||[],idx=arr.findIndex(c=>c.id===id);if(idx<0)return;save.mirrorJumps=(save.mirrorJumps||0)+1;persist();campaign=camp;ui.timeline.classList.add('hidden');ui.menu.classList.add('hidden');loadChapter(idx,{resume:false})})}ui.timelineGrid.innerHTML='';
 for(const camp of ['human','feral']){const col=document.createElement('div');col.className='timelineColumn';col.innerHTML=`<h3>${camp==='human'?'Naru / Taabe':'Feral Predator'}</h3>`;
  for(const c of CONTENT[camp]){const done=(save.completed[camp]||[]).includes(c.id),m=save.mastery[`${camp}:${c.id}`];const n=document.createElement('div');n.className='timelineNode'+(done?' done':'');const continuity=c.persistentEffects?'Continuité persistante':'Événement canonique';n.innerHTML=`<strong>${c.id}${m?.explorer&&m?.survivor?' ★':''}${m?.challenge?' ◆':''}</strong><span>${c.title}<br>${c.location}</span><em>${continuity}</em>`;col.appendChild(n)}
  ui.timelineGrid.appendChild(col)
 }
}
function buildRecords(){if(!ui.recordsGrid)return;const hs=save.statistics.human,fs=save.statistics.feral;const section=(camp,label)=>{const unlocked=new Set(save.records[camp]||[]),defs=CONTENT.records?.[camp]||[];return `<section class="recordSection"><h3>${label}</h3>${defs.map(r=>`<article class="recordCard ${unlocked.has(r.id)?'unlocked':'locked'}"><strong>${unlocked.has(r.id)?r.title:'Archive verrouillée'}</strong><span>${unlocked.has(r.id)?r.text:`Terminer ${r.chapter}`}</span><em>${r.kind}</em></article>`).join('')}</section>`};const cpH=save.resume.human,cpF=save.resume.feral;const marks=new Set(save.huntMarks||[]),ledger=`<section class="recordSection huntLedger"><h3>Marques de chasse Feral · ${marks.size}/${(CONTENT.huntMarks||[]).length}</h3>${(CONTENT.huntMarks||[]).map(m=>`<article class="recordCard ${marks.has(m.id)?'unlocked':'locked'}"><strong>${marks.has(m.id)?m.label:'Marque verrouillée'}</strong><span>${marks.has(m.id)?m.description:`Terminer ${m.chapter}`}</span><em>${m.kind}</em></article>`).join('')}</section>`;ui.recordsGrid.innerHTML=`<div class="recordStats"><div><b>${hs.runs}</b>runs humains</div><div><b>${fs.runs}</b>runs Feral</div><div><b>${Math.round(hs.time+fs.time)}s</b>temps cumulé</div><div><b>${hs.kills+fs.kills}</b>éliminations</div></div><div class="checkpointInfo"><b>Reprises :</b> humains ${cpH?cpH.chapterId+' · objectif '+(cpH.step+1):'aucune'} · Feral ${cpF?cpF.chapterId+' · objectif '+(cpF.step+1):'aucune'} · rejoués miroir ${save.mirrorJumps||0}</div>${ledger}${section('human','Archives de Naru / Taabe')}${section('feral','Registre de chasse Feral')}`}
function buildChallenges(){if(!ui.challengeGrid)return;recomputeMirrors();recomputeFeats();const earned=new Set(save.feats||[]),featCards=(CONTENT.feats||[]).map(f=>`<article class="featCard ${earned.has(f.id)?'on':'locked'}"><strong>${earned.has(f.id)?'✓ ':''}${f.label}</strong><span>${f.description}</span></article>`).join('');const section=(camp,label)=>`<section class="challengeSection"><h3>${label}</h3>${CONTENT[camp].map(c=>{const on=Boolean(save.challenges?.[`${camp}:${c.id}`]);return `<article class="challengeCard ${on?'on':'locked'}"><b>${c.id} · ${c.challenge.label}</b><span>${c.challenge.description}</span><em>${on?'ACCOMPLI':'À ACCOMPLIR'}</em></article>`}).join('')}</section>`;const count=Object.values(save.challenges||{}).filter(Boolean).length;ui.challengeGrid.innerHTML=`<div class="challengeSummary"><b>${count}/37</b><span>défis de chapitre</span><b>${save.feats.length}/12</b><span>hauts faits</span><b>${save.mirrors.length}/15</b><span>dossiers miroir</span></div><div class="featGrid">${featCards}</div>${section('human','Défis Naru / Taabe')}${section('feral','Défis Feral')}`}
function buildCodex(){const grid=$('#codexGrid');grid.innerHTML='';for(const camp of ['human','feral'])for(const c of CONTENT[camp]){const unlocked=save.codex.includes(c.id);const d=document.createElement('div');d.className='codexEntry';d.innerHTML=`<h4>${c.id} · ${unlocked?c.title:'Entrée verrouillée'}</h4><p>${unlocked?`${c.codex.canon}<br><br><b>Adaptation :</b> ${c.codex.adaptation}`:'Terminez ce chapitre pour enregistrer sa fiche.'}</p>`;grid.appendChild(d)}}
$$('[data-start]').forEach(b=>b.onclick=()=>{settings.difficulty=$('#difficulty').value;persist();startCampaign(b.dataset.start)});$('#btnMenu').onclick=()=>ui.menu.classList.remove('hidden');$('#btnTimeline').onclick=()=>{buildTimeline();ui.timeline.classList.remove('hidden')};$('#closeTimeline').onclick=()=>ui.timeline.classList.add('hidden');$('#btnCodex').onclick=()=>{buildCodex();ui.codex.classList.remove('hidden')};$('#closeCodex').onclick=()=>ui.codex.classList.add('hidden');$('#btnRecords').onclick=()=>{buildRecords();ui.records.classList.remove('hidden')};$('#closeRecords').onclick=()=>ui.records.classList.add('hidden');$('#btnChallenges').onclick=()=>{buildChallenges();ui.challenges.classList.remove('hidden')};$('#closeChallenges').onclick=()=>ui.challenges.classList.add('hidden');$('#btnExportSave').onclick=()=>exportSave();$('#btnImportSave').onclick=()=>$('#importSaveInput').click();$('#importSaveInput').onchange=e=>{importSaveFile(e.target.files?.[0]);e.target.value=''};$('#backMenu').onclick=()=>{ui.result.classList.add('hidden');ui.menu.classList.remove('hidden')};$('#replayChapter').onclick=()=>loadChapter(chapterIndex,{resume:false});$('#nextChapter').onclick=()=>{ui.result.classList.add('hidden');if(chapterIndex<chapters().length-1)loadChapter(chapterIndex+1,{resume:false});else ui.menu.classList.remove('hidden')};$('#btnReset').onclick=()=>{if(confirm('Réinitialiser toute la progression PREY V0.6 ?')){save=freshSave();persist();if(campaign)loadChapter(0,{resume:false})}};$('#reducedFlash').onchange=e=>settings.reducedFlash=e.target.checked;$('#aimAssist').onchange=e=>settings.aimAssist=e.target.checked;
$$('[data-touch]').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();const a=b.dataset.touch;if(a==='left')keys.add('PADL');else if(a==='right')keys.add('PADR');else if(a==='up')laneMove(-1);else if(a==='down')laneMove(1);else if(a==='melee')melee();else if(a==='ranged')ranged();else if(a==='interact')interact();else if(a==='vision')state.vision=!state.vision;else if(a==='cloak')toggleC();else if(a==='companion'){if(campaign==='human')useSarii();else{state.weapon=3;useFeralWeapon();renderWeaponRail()}}else if(a==='recall')recallTomahawk();else if(a==='crouch'){state.crouched=!state.crouched}else special()});b.addEventListener('pointerup',()=>{keys.delete('PADL');keys.delete('PADR')})});
window.__PREY_QA__={
 get:()=>({version:6,campaign,chapter:chapter?.id,step:state?.step,stepType:currentStep()?.type,finished:state?.finished,x:state?.x,zone:state?zoneIndex(state.x):null,weapon:state?.weapon,heatHidden:state?.heatHidden,cloak:state?.cloak,shield:state?.shield,maskLost:state?.flags?.maskLost,deaths:state?.deaths,kills:state?.kills,detection:state?.detection,canonIntegrity:state?.canonIntegrity,maxDetection:state?.maxDetection,damageTaken:state?.damageTaken,noise:state?.noise,maxNoise:state?.maxNoise,crouched:state?.crouched,bossPhase:state?.bossPhase,weaponUses:state?[...state.weaponUses]:[],pickups:state?.pickups,ammo:state?.ammo,campaignState:save.campaignState?.[campaign],knowledge:[...save.knowledge],records:save.records?.[campaign]||[],challenges:{...save.challenges},feats:[...save.feats],mirrors:[...save.mirrors],mirrorJumps:save.mirrorJumps||0,huntMarks:[...(save.huntMarks||[])],resume:save.resume?.[campaign]||null}),
 teleport:(z,lane=1)=>{if(!state)return;state.x=zoneCenter(Math.max(0,Math.min(chapter.zones.length-1,z)));state.lane=Math.max(0,Math.min(2,lane));state.y=LANES[state.lane];state.camera=Math.max(0,Math.min(state.worldW-canvas.width,state.x-430));},position:(x,lane=1)=>{if(!state)return;state.x=Math.max(40,Math.min(state.worldW-40,x));state.lane=Math.max(0,Math.min(2,lane));state.y=LANES[state.lane];state.camera=Math.max(0,Math.min(state.worldW-canvas.width,state.x-430));},
 interact:()=>interact(), melee:()=>melee(), ranged:()=>ranged(), special:()=>special(), herb:()=>useHerb(), sarii:()=>useSarii(), cloak:()=>toggleC(), crouch:()=>{state.crouched=!state.crouched;return state.crouched}, vision:()=>{if(!(campaign==='feral'&&state.flags.maskLost))state.vision=!state.vision},
 weapon:(i)=>{if(!state)return;state.weapon=Math.max(0,Math.min((campaign==='feral'?feralWeapons.length:humanWeapons.length)-1,i));state.shield=false;renderWeaponRail();},
 setBossRatio:(ratio)=>{const e=state?.entities.find(e=>e.alive&&['feral','bear','cougar','wolf','taabe','naru'].includes(e.type));if(e){e.hp=e.maxHp*ratio;checkBossStep(e)}},
 setEnemyNear:(type)=>{const e=state?.entities.find(e=>e.alive&&(!type||e.type===type));if(e){e.x=state.x+40;e.y=state.y;return e.id}},
 advance:()=>stepComplete(), checkpoint:()=>snapshotCheckpoint('qa'), restore:()=>restoreResumeSnapshot(false), damage:(type,dmg=999)=>{const e=state.entities.find(e=>e.alive&&e.type===type);if(e)damageEnemy(e,dmg);return window.__PREY_QA__.get()}, killPlayer:()=>{state.health=1;harm(999);return window.__PREY_QA__.get()}, tick:(seconds=1)=>{const n=Math.max(1,Math.ceil(seconds/.05));for(let i=0;i<n;i++)update(.05);return window.__PREY_QA__.get()}
};
const qs=new URLSearchParams(location.search);if(qs.get('campaign')&&CONTENT[qs.get('campaign')]){campaign=qs.get('campaign');const arr=CONTENT[campaign],idx=Math.max(0,arr.findIndex(c=>c.id===qs.get('chapter')));ui.menu.classList.add('hidden');loadChapter(idx,{resume:true})}if(qs.get('unlock')==='1'){save.completed.human=CONTENT.human.map(c=>c.id);save.completed.feral=CONTENT.feral.map(c=>c.id);save.current.human=CONTENT.human.length-1;save.current.feral=CONTENT.feral.length-1;save.codex=[...save.completed.human,...save.completed.feral];persist()}requestAnimationFrame(loop);
